&lt;div class=&quot;min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal outline-none keyboard-focused:focus-ring [.text-message+&amp;amp;]:mt-1&quot; data-message-author-role=&quot;assistant&quot; data-message-id=&quot;d436fc26-5e5b-418f-a80f-feca45e07d07&quot; data-message-model-slug=&quot;gpt-5-5&quot; data-turn-start-message=&quot;true&quot;&gt;
